159	    /// Determine the upgrade selection strategy from the command-line arguments.
160	    pub fn from_args(upgrade: Option<bool>, upgrade_package: Vec<Requirement>) -> Option<Self> {
161	        // Collect the per-package version constraints, skipping requirements with empty specifiers.
162	        let constraints = upgrade_package.iter().fold(
163	            FxHashMap::<PackageName, Vec<Requirement>>::default(),
164	            |mut map, requirement| {
165	                // Skip requirements without a version specifier.
166	                if let RequirementSource::Registry { specifier, .. } = &requirement.source {
167	                    if specifier.is_empty() {
168	                        return map;
169	                    }
170	                }
171	                map.entry(requirement.name.clone())
172	                    .or_default()
173	                    .push(requirement.clone());
174	                map
175	            },
176	        );
177	
178	        match upgrade {
179	            // `--upgrade` upgrades all packages, subject to the collected constraints.
180	            Some(true) => Some(Self {
181	                strategy: UpgradeStrategy::All,
182	                constraints,
183	            }),
184	            // `--no-upgrade` with no `--upgrade-package` retains all pinned versions.
185	            Some(false) if upgrade_package.is_empty() => Some(Self {
186	                strategy: UpgradeStrategy::None,
187	                constraints,
188	            }),
189	            None if upgrade_package.is_empty() => None,
190	            // `--upgrade-package` (with or without `--no-upgrade`) upgrades only the specified
191	            // packages.
192	            Some(false) | None => Some(Self {
193	                strategy: UpgradeStrategy::Packages(
194	                    upgrade_package
195	                        .iter()
196	                        .map(|requirement| requirement.name.clone())
197	                        .collect(),
198	                ),
199	                constraints,
200	            }),
201	        }
